assert len(data) == 100, f"Expected 100 items, got {len(data)}"
allowed_pos = {'noun', 'verb', 'adj', 'adv', 'num', 'intj', 'prep', 'pron', 'conj', 'det'}

for idx, item in enumerate(data):
    assert item["pos"] in allowed_pos, f"Invalid POS {item['pos']} at {idx} ({item['hw']})"
    assert item["ipa"].startswith("/") and item["ipa"].endswith("/") and len(item["ipa"]) > 2, f"Invalid IPA {item['ipa']} at {idx} ({item['hw']})"
    assert item["ipa"].count("/") == 2, f"IPA slashes count != 2 at {idx} ({item['hw']})"
    assert len(item["vi"]) <= 35, f"vi too long ({len(item['vi'])} chars) at {idx} ({item['hw']}): {item['vi']}"
    assert "Số nhiều của" not in item["vi"], f"Found raw artifact at {idx}"
    assert "Xem" not in item["vi"], f"Found raw artifact at {idx}"
    assert item["status"] == "reviewed", f"Status not reviewed at {idx}"

